const GAME_ALIASES = {
    'Dying Light': 'Dying Light 1',
    'Tony Hawk (Xenia)': 'Tony Hawk',
    'Ghost in the Shell': 'Section 9',
};

function metaByDisplay() {
    const map = {};
    for (const meta of Object.values(gameMetadata)) map[meta.display] = meta;
    return map;
}

function enrichWallpaper(item, displayMeta) {
    const game = GAME_ALIASES[item.game] || item.game;
    const meta = displayMeta[game];
    const moods = (item.moods && item.moods.length) ? item.moods : (meta ? meta.moods : ['ambience']);
    return {
        ...item,
        game,
        media: item.media || (meta ? meta.media : 'game'),
        moods,
    };
}

/**
 * Fetches manifest.json and builds the full wallpapers array.
 * Each item: { src, title, game, media, type, moods }
 */
async function loadWallpapers() {
    const displayMeta = metaByDisplay();
    let netlifyImages = [];
    let manifest = (typeof PHOTO_MANIFEST !== 'undefined' && PHOTO_MANIFEST) ? PHOTO_MANIFEST : null;
    if (!manifest) {
        try {
            const res = await fetch('manifest.json');
            if (!res.ok) throw new Error('HTTP ' + res.status);
            manifest = await res.json();
        } catch (err) {
            console.warn('BetterWLPRS: manifest.json not loaded —', err.message);
        }
    }
    if (manifest) {
        for (const [gameKey, files] of Object.entries(manifest)) {
            const meta = gameMetadata[gameKey] || { display: gameKey, media: 'game', moods: ['ambience'] };
            const fileList = Array.isArray(files) ? files : [files];
            for (const filename of fileList) {
                const key = String(filename);
                if (key.toLowerCase().includes('moviewlprs/')) continue;
                // R2 keys are flat filenames (jpg/png). Encode spaces / ! etc.
                const objectKey = key.includes('/') ? key.split('/').map(encodeURIComponent).join('/') : encodeURIComponent(key);
                netlifyImages.push(enrichWallpaper({
                    src: NETLIFY_BASE + objectKey,
                    title: meta.display,
                    game: meta.display,
                    media: meta.media,
                    type: 'image',
                    moods: meta.moods,
                }, displayMeta));
            }
        }
    }
    const videos = localVideos.map((item) => enrichWallpaper(item, displayMeta));
    const movies = movieStills.map((item) => enrichWallpaper(item, displayMeta));
    return [...videos, ...movies, ...netlifyImages];
}

